floor_fn:
"""
    form_name = '{}{}_{}_{}'.format(page_name, page_id, plugin_id, name)
    If we have a form we will compile a id like this id="Kontakt88_plugin7451_SupportView"
    If its a Button Link we will try to compile it like  this id="Kontakt88_plugin7451_Support-Formular"
    If the Button Link Plugin is inside a static placeholder we will use the placeholder.slot and id instead of
    page infos
    """
def update_context_google_tag_manager(
    context: Any,
    page_name: Any = 'NOPAGE_NAME',
    page_id: Any = 'NOPAGE_ID',
    plugin_id: Any = 'NOPLUGIN_ID',
    name: Any = 'NONAME'
) -> object {
    form_name = '{}{}_plugin{}_{}'.format(page_name, page_id, plugin_id, name);
    form_name = form_name.replace(' ', '-');
    context.update({'form_name': form_name});
    return context;
}

test_blocks:
test "t0" {
    assert (
        update_context_google_tag_manager(
            {'request': 'REQUEST'},
            'MYPAGE_NAME',
            'MYPAGE_ID',
            'MYPLUGIN_ID',
            'MYFORM_NAME'
        )
        == {
            'request': 'REQUEST',
            'form_name': 'MYPAGE_NAMEMYPAGE_ID_pluginMYPLUGIN_ID_MYFORM_NAME'
        }
    );;
}

test "t1" {
    assert (
        update_context_google_tag_manager(
            {}, 'Contact', 'contact', '7451', 'Support-Formular'
        )
        == {'form_name': 'Contactcontact_plugin7451_Support-Formular'}
    );;
}

test "t2" {
    assert (
        update_context_google_tag_manager(
            {}, 'Contact', 'contact', '7451', 'SupportView'
        )
        == {'form_name': 'Contactcontact_plugin7451_SupportView'}
    );;
}
